import{_ as s,D as o,c,I as t,j as e,a,a4 as n,o as l}from"./chunks/framework.CRCV4hx_.js";const k=JSON.parse('{"title":"Dynamic Pricing","description":"","frontmatter":{},"headers":[],"relativePath":"dynamic-pricing.md","filePath":"dynamic-pricing.md"}'),p={name:"dynamic-pricing.md"},d=n('<h1 id="dynamic-pricing" tabindex="-1">Dynamic Pricing <a class="header-anchor" href="#dynamic-pricing" aria-label="Permalink to &quot;Dynamic Pricing&quot;">​</a></h1><p>Dynamic pricing is a powerful feature that allows you to change the price of a reservation based on various conditions. It’s essentially a fancy term for <em>campaigns</em> or <em>discounts</em>, but it also allows you to increase the price of a reservation if that&#39;s something you want to do. In this section, we’ll go over how to set up and use dynamic pricing.</p><h2 id="basics" tabindex="-1">Basics <a class="header-anchor" href="#basics" aria-label="Permalink to &quot;Basics&quot;">​</a></h2><p>You can set up dynamic pricing by navigating to (you guessed it) the <strong>Dynamic Pricing</strong> section in your Statamic Control Panel. To create a new Dynamic Pricing campaign, simply click on the &quot;Add Dynamic Pricing&quot; button.</p>',4),h=n('<p>This list supports <em>drag and drop</em> to reorder the campaigns. Resrv processes the list in sequence and applies each dynamic pricing rule <strong>in order</strong> to the reservation.</p><div class="info custom-block"><p class="custom-block-title">INFO</p><p>The system doesn’t add the discounts together and apply them all at once. Instead, it applies them one by one. For example, if you have a reservation that costs $100 and two dynamic pricing rules are applied in order, say 10% and 20%, the system will first apply the 10% discount, reducing the cost to $90. Then, it applies the 20% discount, further reducing the price to $72. It will not apply a 30% discount, which would reduce the price to $70.</p></div><h2 id="general-settings" tabindex="-1">General settings <a class="header-anchor" href="#general-settings" aria-label="Permalink to &quot;General settings&quot;">​</a></h2><p>Each Dynamic Pricing campaign should have a title. You can then select the amount by which the price should be increased or decreased, either as a percentage or a fixed amount. Additionally, you need to <strong>assign</strong> the dynamic pricing to specific Entries or Extras.</p><p>You can also set an expiry date, after which the dynamic pricing will no longer be applied.</p><p>Enabling the <strong>Overrides all other dynamic pricing</strong> option ensures that <strong>only</strong> this dynamic pricing will be applied if the conditions match. If multiple campaigns are set as overriding, the system will apply only the first one in order. This is useful if you want to create non-combining discounts.</p>',6),m=n('<h2 id="conditions" tabindex="-1">Conditions <a class="header-anchor" href="#conditions" aria-label="Permalink to &quot;Conditions&quot;">​</a></h2><p>Each Dynamic Pricing campaign has a set of conditions that determine when the campaign should be applied. You can use the following conditions:</p><ul><li><p><strong>Date conditions</strong>: Set a date range to specify when the campaign should be applied. You can choose:</p><ul><li>If all dates in a reservation should fall within that range (for multiple-day reservations).</li><li>If only the reservation start date should fall within the range.</li><li>If the majority of the reservation dates should be within the range (e.g., for a 7-day reservation, at least 4 days must be within the date range).</li></ul></li><li><p><strong>Reservation conditions</strong>: Apply dynamic pricing only to reservations that meet specific criteria, such as equal to, not equal to, greater than, less than, or greater than or equal to. The available options are:</p><ul><li><em>Reservation duration</em> (in days)</li><li><em>Reservation price</em></li><li><em>Difference in days between the reservation start date and the current date</em></li></ul></li></ul>',3),u=e("h2",{id:"coupons",tabindex:"-1"},[a("Coupons "),e("a",{class:"header-anchor",href:"#coupons","aria-label":'Permalink to "Coupons"'},"​")],-1),g=e("p",null,"You can set up coupons to apply a discount to a reservation. Simply enter a coupon code of your choice in the appropriate field. The user can then use this coupon code during checkout to apply the discount.",-1),y=e("p",null,[a("Please note that coupons "),e("strong",null,"always"),a(" get applied, even if there are overriding dynamic pricing campaigns in place. You can also apply the other conditions mentioned above to coupons, such as limiting their use to a specific date range.")],-1),f={id:"minimum-and-maximum-prices",tabindex:"-1"},_=e("a",{class:"header-anchor",href:"#minimum-and-maximum-prices","aria-label":'Permalink to "Minimum and maximum prices <Badge type="tip" text="NEW" />"'},"​",-1),b=n('<p>In addition to <strong>Increase</strong> and <strong>Decrease</strong>, the Operation field offers two more values that let you set a price floor or cap:</p><table tabindex="0"><thead><tr><th>Operation</th><th>Effect</th></tr></thead><tbody><tr><td><strong>Minimum</strong></td><td>If the computed price falls below this amount, it is raised up to this amount (a floor).</td></tr><tr><td><strong>Maximum</strong></td><td>If the computed price rises above this amount, it is lowered down to this amount (a cap).</td></tr></tbody></table><p>When you choose <strong>Minimum</strong> or <strong>Maximum</strong>, the <strong>Type</strong> is forced to <strong>Fixed</strong>: a clamp is always a fixed monetary amount (e.g. floor at <code>150</code>, cap at <code>250</code>). Percentage clamps are not supported.</p><h3 id="when-clamps-are-evaluated" tabindex="-1">When clamps are evaluated <a class="header-anchor" href="#when-clamps-are-evaluated" aria-label="Permalink to &quot;When clamps are evaluated&quot;">​</a></h3><p>Clamps are special: they always run <strong>after</strong> everything else, regardless of where you drag them in the list. The price is computed in two phases:</p><ol><li>All <strong>Increase</strong> and <strong>Decrease</strong> rules run first, one by one, in their drag-and-drop order (exactly as described above).</li><li>The <strong>Minimum</strong> and <strong>Maximum</strong> clamps run last, against the final computed price.</li></ol><p>This means a clamp also runs <strong>after</strong> an &quot;Overrides all other dynamic pricing&quot; rule and <strong>after</strong> any coupon has been applied, so it always evaluates the truly final price.</p><div class="info custom-block"><p class="custom-block-title">INFO</p><p>For example, a base price of $200 with a 50% discount becomes $100. A <strong>Minimum</strong> clamp of <code>150</code> then lifts it back up to $150. The clamp still wins even if the discount came from an overriding campaign or a coupon.</p></div><p>A few more details worth knowing:</p><ul><li>A <strong>Minimum</strong> only raises the price when it is below the floor, and a <strong>Maximum</strong> only lowers it when it is above the cap, otherwise the price is left untouched.</li><li>If a misconfigured <strong>Decrease</strong> would drive the price below zero, the result is floored at <code>0</code>. This safety floor is applied after the min/max clamps, so a configured minimum still takes precedence.</li><li>Clamps also apply to <a href="./extras">Extra</a> prices. For a per-day extra, the clamp is evaluated against the extra&#39;s total for the booking (price × days), not the per-unit price.</li></ul><h2 id="applied-dynamic-pricing" tabindex="-1">Applied Dynamic Pricing <a class="header-anchor" href="#applied-dynamic-pricing" aria-label="Permalink to &quot;Applied Dynamic Pricing&quot;">​</a></h2><p>On the <a href="./reservations#reservation-details">Reservation Details</a> page in the Control Panel, you can view which dynamic pricing campaigns have been applied to a reservation.</p>',12);function v(w,T,x,P,I,A){const i=o("Image"),r=o("Badge");return l(),c("div",null,[d,t(i,{src:"./img/resrv-dynamic-pricing.webp",alt:"The Dynamic Pricing section in the Control Panel."}),h,t(i,{src:"./img/resrv-dynamic-pricing-off.webp",alt:"A dynamic pricing that applies a discount of 10% for reservations that are for August 2025."}),m,t(i,{src:"./img/resrv-dynamic-pricing-lastminute.webp",alt:"A dynamic pricing that only applies to reservations that start in the next 7 days."}),u,g,y,e("h2",f,[a("Minimum and maximum prices "),t(r,{type:"tip",text:"NEW"}),a(),_]),b,t(i,{src:"./img/resrv-dynamic-pricing-applied.webp",alt:"The applied dynamic pricing campaigns in the reservation details page."})])}const q=s(p,[["render",v]]);export{k as __pageData,q as default};
